package main

import (
	"context"
	"fmt"
	"log"
	"strings"

	"github.com/jackc/pgx/v5"
)

func main() {
	rawData := `INSERT INTO houses_data (house_name, zodiac_sign, core_meaning, in_real_life, strengths, challenges, relationships, path_of_growth) VALUES
('House 10', 'Aries', 'Career, public image, and reputation are driven by ambition, independence, and a desire to pioneer. You want to be the boss.', 'You are highly competitive in your professional life. You likely forge your own path, preferring entrepreneurship or leadership roles over taking orders.', 'Fearless ambition, the ability to initiate major professional projects, natural executive presence, and a courageous public image.', 'Impatience with career progression, conflict with authority figures, a tendency to quit when bored, and coming across as overly aggressive in public.', 'You need a partner who supports your intense ambitions and understands that your career is a battlefield you intend to conquer.', 'Learn that true leadership involves guiding others, not just conquering them. Cultivate patience for the long-term grind of career building.'),
('House 10', 'Taurus', 'Career and public image are built on stability, endurance, and material success. You seek a reputation for absolute reliability.', 'You climb the career ladder slowly but steadily. You prefer established, secure industries (like finance, real estate, or agriculture) and project a calm, unshakable public persona.', 'Unwavering professional endurance, the ability to manage massive projects over long periods, and an excellent reputation for producing high-quality work.', 'Stubborn resistance to changing career paths, staying in unfulfilling jobs purely for financial security, and a fear of taking professional risks.', 'You view your career as a means to provide for your family. You need a partner who values your steady ambition and respects your need for a predictable work life.', 'Embrace innovation in your career. Understand that taking calculated risks is sometimes necessary to achieve true professional greatness.'),
('House 10', 'Gemini', 'Career, public image, and reputation are centered around communication, adaptability, and intellectual versatility. You are known for your brilliant mind.', 'You likely have multiple careers simultaneously or work in fields requiring constant communication (writing, speaking, sales, media). Your public image is youthful and dynamic.', 'Exceptional networking skills, the ability to adapt instantly to changing professional landscapes, and a talent for communicating complex ideas to the public.', 'Career restlessness, a lack of deep focus that prevents you from reaching the absolute top of a single field, and a reputation for being somewhat scattered.', 'You need a partner who can keep up with your fast-paced public life and understands that your career requires constant socializing.', 'Develop professional discipline. Pick one or two primary fields and dedicate yourself to mastering them deeply rather than skimming the surface of many.'),
('House 10', 'Cancer', 'Career and public image are deeply tied to nurturing, emotion, and providing security. You are known as the "caretaker" in your professional sphere.', 'You may work in fields related to food, housing, counseling, or childcare. You lead with empathy, and your public image is often that of a protective, parental figure.', 'Profound emotional intelligence in the workplace, the ability to create a "family" atmosphere among colleagues, and a genuine dedication to serving the public.', 'Taking professional criticisms too personally, a fear of stepping into the public eye due to emotional vulnerability, and letting your moods dictate your career path.', 'Your career choices are often driven by the need to secure your family''s future. You need a partner who supports your deep emotional investment in your work.', 'Learn to separate your professional reputation from your core self-worth. Develop a thicker skin so that public criticism does not devastate you.'),
('House 10', 'Leo', 'Career, public image, and reputation are dramatic, radiant, and larger than life. You demand to be recognized as a star in your field.', 'You gravitate toward careers that offer a stage—entertainment, politics, or high-level management. You have a commanding public presence and expect respect and admiration.', 'Immense professional charisma, natural leadership abilities, a warm and inspiring public persona, and the courage to take on massive public responsibilities.', 'Arrogance, an excessive need for public validation, dominating colleagues, and suffering deep career crises if you feel unappreciated or ignored.', 'You expect your partner to be your biggest fan and to support your rise to the top. You want a relationship that looks good in the public eye.', 'Learn that true professional greatness does not always require applause. Find validation in the quality of your work, not just in the public''s reaction to it.'),
('House 10', 'Virgo', 'Career and public image are built on service, analytical brilliance, and absolute competence. You are known as the person who gets things done perfectly.', 'You are highly modest about your achievements, preferring to work quietly behind the scenes. You excel in fields requiring precision, analysis, or healthcare.', 'Unmatched professional competence, a relentless work ethic, brilliant problem-solving skills, and a pristine reputation for reliability and accuracy.', 'Extreme perfectionism that delays career progress, a tendency to accept subordinate roles despite having the skills to lead, and crippling self-criticism.', 'You view your career as your primary duty. You need a partner who respects your long hours and understands that you express love through practical achievement.', 'Learn to accept praise for your hard work and do not be afraid to step into leadership roles. Silence your inner critic and recognize your immense professional value.'),
('House 10', 'Libra', 'Career, public image, and reputation are centered around diplomacy, aesthetics, and partnership. You are known for your charm and fair-mindedness.', 'You excel in fields requiring mediation, law, art, or public relations. You have a highly refined public image and strive to maintain excellent relationships with authority figures.', 'Exceptional diplomacy in the workplace, a talent for creating beautiful or harmonious public works, and the ability to navigate complex professional politics effortlessly.', 'Indecisiveness regarding your career path, compromising your own professional goals to please bosses or partners, and a fear of making unpopular executive decisions.', 'You often prefer to work in business partnerships rather than alone. You need a supportive spouse to feel truly balanced in your public life.', 'Develop the courage to stand alone professionally. Learn that true leadership sometimes requires making decisions that will temporarily disrupt the peace.'),
('House 10', 'Scorpio', 'Career and public image are intense, transformative, and deeply powerful. You seek absolute control and profound impact in your professional life.', 'You are drawn to careers involving investigation, psychology, crisis management, or hidden resources. You guard your public reputation fiercely and possess a magnetic, intimidating authority.', 'Incredible resilience in overcoming career setbacks, the ability to wield immense professional power, and profound insight into the hidden dynamics of your industry.', 'Paranoia regarding colleagues or competitors, an obsessive need for control that alienates others, and a tendency to engage in ruthless professional power struggles.', 'You are intensely private about your career ambitions. You demand absolute loyalty from business partners and will quickly cut ties if betrayed.', 'Use your immense professional power to heal and transform your industry, not just to control it. Learn to trust your colleagues and delegate authority.'),
('House 10', 'Sagittarius', 'Career, public image, and reputation are expansive, optimistic, and philosophical. You seek a career that offers freedom and the opportunity to teach or travel.', 'You are known for your visionary ideas and infectious enthusiasm. You likely work in fields involving higher education, publishing, international business, or travel.', 'Boundless professional optimism, the ability to inspire massive audiences, a global perspective on your industry, and a joyful approach to your public life.', 'A lack of follow-through on grand career visions, ignoring the mundane details required for success, and a reputation for being unreliable or overly blunt.', 'You need a partner who understands that your career requires immense freedom and perhaps frequent travel. You cannot thrive in a restrictive domestic environment.', 'Cultivate professional discipline. Learn that achieving grand visions requires mastering the boring, mundane details. Ground your optimism in practical reality.'),
('House 10', 'Capricorn', 'Career, public image, and reputation are the absolute core of your existence. You are driven by a relentless ambition to achieve ultimate authority and status.', 'This is the natural home of Capricorn. You are highly disciplined, stoic, and willing to work for decades to achieve your goals. You project an aura of absolute competence and traditional authority.', 'Unmatched executive functioning, the ability to build lasting professional empires, incredible resilience, and a pristine reputation built on hard work.', 'Workaholism, emotional coldness in public, prioritizing career success over all personal relationships, and a deep-seated fear of public failure.', 'Your career often takes precedence over your relationships. You seek a partner who is equally ambitious or who is willing to fully support your ascent to the top.', 'Remember that you are more than your job title. Cultivate a life outside of your career and allow yourself to experience joy and emotional connection without feeling guilty.'),
('House 10', 'Aquarius', 'Career and public image are unconventional, progressive, and focused on collective advancement. You are known as an innovator or a rebel in your field.', 'You are drawn to careers involving technology, science, or social reform. You reject traditional corporate structures, preferring to work independently or in egalitarian groups.', 'Brilliant professional originality, the courage to challenge outdated industry norms, a humanitarian approach to business, and a highly unique public persona.', 'Rebelling against authority just to be contrary, emotional detachment that alienates colleagues, and an unpredictable career path that lacks stability.', 'You view your professional network as a community. You need a partner who respects your unconventional career choices and your need for absolute intellectual freedom.', 'Learn to integrate your brilliant innovations into existing structures. True reform often requires working from within the system rather than just rebelling against it from the outside.'),
('House 10', 'Pisces', 'Career, public image, and reputation are fluid, spiritual, and deeply empathetic. You seek a profession that allows you to heal others or express profound artistry.', 'You are drawn to careers in the arts, healing professions, or spirituality. Your public image is often mysterious, glamorous, or perceived as deeply compassionate and sacrificing.', 'Immense creative and spiritual inspiration in your work, the ability to touch the masses on an emotional level, and a profound dedication to serving humanity.', 'A lack of professional boundaries, chronic disorganization, getting lost in career fantasies rather than taking practical steps, and a tendency to play the victim in the workplace.', 'You often merge your career with your spiritual or romantic ideals. You need a highly grounded partner to help manage the practical details of your public life.', 'Ground your vast professional dreams in practical reality. Establish strong boundaries so that your compassion is not exploited by your industry or your colleagues.'),
('House 11', 'Aries', 'Friendships, group associations, and collective aspirations are approached with energy, leadership, and a pioneering spirit. You want to lead the pack.', 'You are the initiator in your social circle, always organizing activities or championing new causes. You attract energetic, independent friends and prefer active group settings.', 'Natural leadership within organizations, the courage to fight for collective goals, and an infectious enthusiasm that motivates your network.', 'Dominating friend groups, impulsiveness that alienates more cautious allies, a tendency to argue with friends, and losing interest in causes quickly.', 'You need friends who respect your independence and can match your high energy. You may clash with overly sensitive individuals in group settings.', 'Learn to be a team player, not just the team captain. True collective progress requires listening to the ideas of others and compromising.'),
('House 11', 'Taurus', 'Friendships and collective aspirations are built on stability, loyalty, and shared values. You seek a social circle that is reliable and deeply grounded.', 'You take a long time to make friends, but once you do, they are friends for life. You prefer small, intimate group gatherings centered around good food, art, or nature.', 'Unwavering loyalty to your network, the ability to provide practical support to organizations, and a calming, steady presence in any group setting.', 'Stubbornness within group dynamics, a reluctance to welcome new people into your established circle, and prioritizing material status in your friendships.', 'You view your friends as an extension of your family. You require absolute reliability from your social network and express care through tangible support.', 'Be open to new associations and unconventional ideas. Do not let your need for comfort prevent you from engaging with diverse groups of people.'),
('House 11', 'Gemini', 'Friendships, group associations, and aspirations are centered around communication, variety, and intellectual exchange. Your network is vast and diverse.', 'You are a social butterfly, belonging to numerous different groups and clubs. You love networking, sharing information, and connecting people with disparate interests.', 'Exceptional networking skills, the ability to bridge communication gaps within organizations, and a brilliant, adaptable approach to collective goals.', 'Superficial friendships, a lack of deep loyalty to any single group, a tendency to gossip, and scattering your social energy too thinly.', 'You need friends who are intellectually stimulating and constantly changing. You quickly lose interest in social circles that become stagnant or overly emotional.', 'Cultivate depth in your friendships. While having a vast network is a strength, taking the time to build profound, lasting bonds with a few individuals is equally important.'),
('House 11', 'Cancer', 'Friendships and collective aspirations are deeply emotional, nurturing, and protective. You treat your close friends like family and seek a "tribe" for emotional security.', 'You are drawn to groups that focus on caregiving, community support, or shared heritage. You are fiercely protective of your social circle and often take on a maternal role within groups.', 'Profound emotional support for your network, the ability to create a deep sense of belonging within organizations, and fierce loyalty to your "tribe."', 'Cliquishness, a fear of outsiders, taking group disagreements intensely personally, and a tendency to smother friends with over-protectiveness.', 'You need a social circle where you feel completely emotionally safe. You express your friendship through cooking, nurturing, and offering a shoulder to cry on.', 'Learn to establish emotional boundaries within your friendships. Understand that not everyone in your group needs to be "mothered," and practice welcoming new faces without suspicion.'),
('House 11', 'Leo', 'Friendships, group associations, and aspirations are dramatic, warm, and tied to pride. You want to be the shining center of your social network.', 'You are generous, popular, and often take on leadership roles in clubs or organizations. You love hosting grand social events and expect admiration from your peers.', 'Immense generosity toward friends, charismatic leadership within groups, the ability to inspire collective joy, and unwavering loyalty to your inner circle.', 'Arrogance, a need to constantly be the center of attention in group settings, dominating conversations, and turning friendships into a stage for your ego.', 'You expect your friends to be your biggest fans and to treat you with respect. You are deeply hurt if you feel ignored or unappreciated by your network.', 'Learn that true friendship involves sharing the spotlight. Allow your friends to shine and realize that you do not always have to be the leader to be loved.'),
('House 11', 'Virgo', 'Friendships and collective aspirations are built on practical service, organization, and mutual improvement. You show you care by helping your network succeed.', 'You are the friend everyone calls when they need practical advice or help moving. You prefer groups focused on health, service, or intellectual improvement rather than loud parties.', 'Unmatched reliability as a friend, the ability to organize complex group efforts flawlessly, and a humble, dedicated approach to serving your community.', 'Over-analyzing your friendships, being overly critical of your peers, nitpicking group operations, and a tendency to feel underappreciated for your quiet service.', 'You express friendship through acts of service and expect competence from your social circle. You have little patience for messy or dramatic friends.', 'Learn to relax and just enjoy the company of others without needing to "fix" them. Accept your friends'' imperfections and recognize your own intrinsic worth beyond what you can do for them.'),
('House 11', 'Libra', 'Friendships, group associations, and aspirations are centered around harmony, aesthetics, and social justice. Your network is essential for your sense of balance.', 'You are highly popular, diplomatic, and skilled at bringing people together. You prefer refined social settings and often act as the peacemaker within your friend group.', 'Exceptional mediation skills within organizations, a talent for creating beautiful and harmonious social events, and a deep dedication to fairness and equality in groups.', 'Indecisiveness, agreeing with the group just to keep the peace (groupthink), a fear of confronting toxic friends, and relying too heavily on your social network for your identity.', 'You thrive in partnerships and cooperative group settings. You detest crude behavior or conflict within your social circle and will go to great lengths to maintain harmony.', 'Develop the courage to stand alone and voice unpopular opinions. True friendship requires honesty, even when it disrupts the peace.'),
('House 11', 'Scorpio', 'Friendships and collective aspirations are intense, transformative, and deeply private. You seek absolute loyalty and profound psychological connection with your peers.', 'You prefer a very small, tightly-knit circle of fiercely loyal friends over a large network of acquaintances. You are drawn to groups involved in psychology, investigation, or the occult.', 'Unwavering loyalty to your inner circle, the ability to support friends through massive psychological crises, and profound insight into group dynamics.', 'Paranoia regarding outsiders, extreme possessiveness or jealousy in friendships, holding long-term grudges, and a tendency to engage in power struggles within organizations.', 'You demand absolute transparency and trust from your friends. Betrayal is unforgivable. You are a formidable ally but a terrifying enemy.', 'Learn to trust people outside your immediate circle. Release the need to control your friendships and realize that not everyone has hidden, malicious motives.'),
('House 11', 'Sagittarius', 'Friendships, group associations, and aspirations are expansive, optimistic, and philosophical. You seek a network that shares your visionary ideals and love for freedom.', 'You have friends all over the world from diverse cultures and backgrounds. You are drawn to philosophical, religious, or travel-oriented groups and bring immense joy to your social circle.', 'An inspiring, joyful approach to collective goals, the ability to unite diverse groups of people, and boundless optimism regarding humanity''s future.', 'A lack of deep commitment to any single group, unreliability as a friend due to constant traveling or changing interests, and a lack of tact that can offend peers.', 'You need absolute freedom within your friendships. Clingy or overly emotional friends make you feel trapped. You bond over shared ideas and adventures.', 'Cultivate discipline and loyalty in your friendships. While having a global network is wonderful, make sure you are also present and reliable for the people who truly count on you.'),
('House 11', 'Capricorn', 'Friendships and collective aspirations are structured, ambitious, and focused on long-term achievements. You view your network as a professional asset.', 'You are highly selective about your friends, preferring individuals who are mature, successful, or influential. You often take on administrative or leadership roles within organizations.', 'Exceptional reliability, the ability to manifest grand collective goals through strategic planning, and a steadfast, mature approach to supporting your network.', 'Viewing friendships purely as networking opportunities, emotional coldness within social groups, pessimism, and a fear of letting your guard down to simply have fun.', 'You express care through mentorship and practical support. You respect authority and structure within groups and have little patience for disorganized or frivolous social circles.', 'Remember that friendships are about emotional connection, not just professional advancement. Allow yourself to be vulnerable and enjoy the simple pleasure of human companionship.'),
('House 11', 'Aquarius', 'Friendships, group associations, and aspirations are the absolute core of your existence. You are a true humanitarian, dedicated to progressive collective goals.', 'This is the natural home of Aquarius. You thrive in large, diverse groups and are often the eccentric innovator within your social circle. You are deeply committed to social reform.', 'Brilliant originality in approaching collective problems, a profound dedication to equality and human rights, and an incredibly tolerant, open-minded approach to networking.', 'Emotional detachment that makes friends feel you don''t truly care about them individually, extreme stubbornness regarding your utopian ideals, and rebelling against group consensus.', 'You view the entire world as your community. You are a fiercely loyal friend but require immense personal space and intellectual freedom within your social circle.', 'Learn to connect with individuals on a deep, emotional level, not just as part of a collective. True humanitarianism requires empathy for the individual heart, not just the abstract masses.'),
('House 11', 'Pisces', 'Friendships and collective aspirations are fluid, spiritual, and deeply empathetic. You seek a mystical or artistic connection with your social network.', 'You are drawn to groups focused on spirituality, art, or charity. You absorb the emotional energy of your friends easily and are incredibly compassionate toward the suffering of others.', 'Boundless empathy for your social circle, the ability to inspire groups with your spiritual vision, and a profound, selfless dedication to helping those in need.', 'A lack of boundaries that leads to toxic friendships, getting lost in group illusions or cults, emotional exhaustion from absorbing others'' pain, and extreme flakiness.', 'You seek soul-level connections with your friends. You are highly adaptable in group settings but must be careful not to lose your own identity in the collective energy.', 'Establish firm emotional boundaries. Learn to differentiate your own feelings from those of your friends, and realize that you cannot save everyone. Ground your compassion in practical reality.'),
('House 12', 'Aries', 'The subconscious, hidden matters, and spirituality are characterized by repressed anger, hidden courage, and a secret desire to pioneer. Your inner world is a battlefield.', 'You may project a calm exterior but struggle with intense, hidden frustrations or impulsive urges. You often prefer to work entirely alone and may act as a secret pioneer or hidden leader.', 'The ability to fight fiercely for the underdog in secret, immense hidden reserves of energy that emerge in crises, and courage in exploring the deepest psychological shadows.', 'Repressed anger that erupts unexpectedly, self-sabotage through impulsive, hidden actions, and a fear of expressing your true assertiveness openly.', 'Your spiritual journey requires confronting your inner warrior. You may feel isolated because you hide your most passionate, driven self from the world.', 'Bring your hidden anger and desires into the light. Learn healthy ways to assert yourself publicly so that your repressed energy does not destroy you from within.'),
('House 12', 'Taurus', 'The subconscious, hidden matters, and spirituality are tied to repressed materialism, hidden stubbornness, and a deep, secret need for absolute stability.', 'You may hide your true desires for luxury or material wealth, projecting a detached exterior. Your spiritual journey involves grounding yourself, often finding peace in isolated natural settings.', 'A profound, hidden endurance, the ability to manifest material results quietly behind the scenes, and a deeply sensual, unspoken connection to nature and spirituality.', 'Repressed greed or materialism, an extreme fear of financial loss that dictates your subconscious actions, and a stubborn refusal to let go of hidden emotional baggage.', 'You seek spiritual peace through physical comfort and silence. You are a reliable, unseen supporter of others, often providing material help anonymously.', 'Acknowledge your material desires without guilt. True spiritual growth requires realizing that the physical world and the spiritual world are not mutually exclusive.'),
('House 12', 'Gemini', 'The subconscious, hidden matters, and spirituality are characterized by mental restlessness, hidden anxieties, and a secret, vast inner dialogue.', 'Your mind is constantly racing, even when you appear calm. You may struggle with insomnia or hidden nervous tension. You find spiritual connection through isolated study, writing, or quiet contemplation.', 'A brilliant, intuitive mind that operates behind the scenes, the ability to act as a secret communicator or writer, and a profound, hidden understanding of duality.', 'Repressed anxiety, an inability to quiet the mind during meditation, keeping your true thoughts a secret out of fear of judgment, and self-sabotage through overthinking.', 'Your spiritual journey requires calming the mental noise. You may struggle to communicate your deepest, most profound insights, preferring to keep them hidden.', 'Practice meditation and mindfulness to silence your inner chatter. Learn to trust your intuition rather than constantly analyzing your subconscious feelings.'),
('House 12', 'Cancer', 'The subconscious, hidden matters, and spirituality are profoundly emotional, deeply intuitive, and tied to hidden ancestral or childhood trauma.', 'You absorb the emotions of the world like a sponge and require frequent periods of total isolation to emotionally recharge. Your inner world is a vast, sensitive ocean of memory and feeling.', 'Supreme emotional intuition, the ability to heal others on a profound, unspoken level, and a deep, mystical connection to your ancestors and the collective unconscious.', 'Repressed childhood trauma, debilitating hidden fears of abandonment, playing the martyr in secret, and self-sabotaging out of a deep-seated feeling of emotional insecurity.', 'Your spiritual path involves nurturing your own soul. You are a powerful, hidden healer who deeply understands the unspoken pain of humanity.', 'Confront your hidden emotional wounds. Do not retreat into isolation permanently; learn to establish boundaries so you can share your immense empathy with the world safely.'),
('House 12', 'Leo', 'The subconscious, hidden matters, and spirituality are characterized by repressed pride, hidden creativity, and a secret desire for grand recognition.', 'You may hide your true creative talents or your desire for the spotlight, perhaps feeling unworthy of attention. You often perform great acts of generosity anonymously or work as a hidden leader.', 'Immense, hidden creative power, a deeply warm and radiant inner life, and the ability to inspire and lead others from behind the scenes without seeking credit.', 'Repressed ego that manifests as secret vanity or bitterness, self-sabotaging your own success out of a fear of public failure, and hiding your true, radiant self.', 'Your spiritual journey requires acknowledging your own intrinsic worth. You have a profound capacity for unconditional love that you often keep hidden from the world.', 'Allow your inner light to shine publicly. Do not hide your talents or your pride out of a false sense of modesty. You deserve to be seen.'),
('House 12', 'Virgo', 'The subconscious, hidden matters, and spirituality are analytical, highly critical, and focused on hidden acts of service. Your inner world is meticulously organized.', 'You may struggle with hidden anxieties regarding your health or competence. You find spiritual peace through quiet, practical service to others or through solitary, detailed work.', 'A profound ability to analyze the subconscious mind, selfless dedication to helping the most marginalized in society, and exceptional behind-the-scenes organizational skills.', 'Crippling, hidden self-criticism, psychosomatic illnesses driven by repressed anxiety, and self-sabotage by obsessing over minor flaws in your own psyche.', 'Your spiritual path involves realizing that perfection is an illusion. You are a quiet, humble servant to humanity, often doing the difficult work that no one else wants to do.', 'Silence your hidden inner critic. Learn to accept yourself unconditionally and realize that your worth is not defined by how perfectly you serve others.'),
('House 12', 'Libra', 'The subconscious, hidden matters, and spirituality are centered around a repressed need for harmony, hidden codependency, and a secret desire for ideal partnership.', 'You may hide your true opinions to avoid conflict, harboring secret resentments. You find spiritual peace in beautifully aesthetic, isolated environments and may act as a hidden peacemaker.', 'A profound, unspoken understanding of human relationships, the ability to restore balance behind the scenes, and a deeply refined, artistic inner life.', 'Repressed anger due to people-pleasing, self-sabotaging through hidden codependent behaviors, and a fear of confronting your own shadow self because it is "ugly."', 'Your spiritual journey requires finding inner balance independent of any partner. You possess a beautiful soul, but you often suppress your own needs for the sake of artificial peace.', 'Confront your hidden resentments. True spiritual harmony requires acknowledging both the light and the dark within yourself, and asserting your own needs openly.'),
('House 12', 'Scorpio', 'The subconscious, hidden matters, and spirituality are intensely powerful, deeply transformative, and focused on hidden psychological depths.', 'You possess a terrifyingly accurate intuition and are drawn to the deepest mysteries of the occult and human psychology. Your inner world is a crucible of intense, hidden passions and fears.', 'Unmatched psychological depth, the ability to heal the most profound traumas in yourself and others, and immense spiritual power that operates unseen.', 'Repressed paranoia, hidden obsessions, holding onto dark secrets that poison your soul, and self-sabotage through a subconscious desire for destruction.', 'Your spiritual path is one of radical transformation. You must continually let go of your ego and face the darkest parts of your soul to achieve true enlightenment.', 'Do not fear your own intensity. Bring your hidden fears and desires into the light where they can be healed. Use your immense power for spiritual regeneration, not self-destruction.'),
('House 12', 'Sagittarius', 'The subconscious, hidden matters, and spirituality are expansive, philosophical, and driven by a secret desire for boundless freedom.', 'You may hide your true philosophical beliefs or your desire to escape the mundane world. You find profound spiritual connection through solitary travel or isolated study of grand concepts.', 'A vast, visionary inner life, the ability to act as a hidden spiritual guide or teacher, and profound, unspoken optimism and faith in the universe.', 'Repressed restlessness, self-sabotage through hidden recklessness or gambling, and a tendency to run away from reality by retreating into grand, unrealistic fantasies.', 'Your spiritual journey involves finding ultimate truth within yourself. You possess a deep, innate wisdom that you often share quietly with those who are lost.', 'Ground your spiritual visions in reality. You do not need to constantly escape to find truth; true freedom and wisdom can be found exactly where you are.'),
('House 12', 'Capricorn', 'The subconscious, hidden matters, and spirituality are structured, deeply serious, and characterized by repressed ambition and hidden fears of failure.', 'You may project a carefree exterior while harboring intense, secret ambitions or heavy burdens of guilt. You find spiritual strength through solitude, discipline, and facing harsh realities.', 'Immense, hidden resilience, the ability to bear incredible psychological burdens without complaining, and a profound, stoic spiritual wisdom acquired through hardship.', 'Repressed pessimism, crippling hidden guilt or fear of inadequacy, self-sabotaging your own joy out of a belief that you must suffer, and emotional isolation.', 'Your spiritual path requires dismantling the rigid structures of your ego. You are a silent pillar of strength for others, often carrying the weight of the world in secret.', 'Release your hidden guilt and your need for absolute control. True spiritual mastery requires vulnerability and the ability to forgive yourself for not being perfect.'),
('House 12', 'Aquarius', 'The subconscious, hidden matters, and spirituality are unconventional, progressive, and characterized by a hidden feeling of alienation from humanity.', 'You may feel like an alien observing the world, hiding your true, eccentric brilliance for fear of rejection. You find spiritual peace through solitary intellectual pursuits or hidden humanitarian work.', 'A brilliant, profoundly original subconscious mind, the ability to channel futuristic or collective insights, and a selfless, detached dedication to helping the marginalized.', 'Repressed rebellion that erupts inappropriately, a deep, hidden fear of intimacy that isolates you, and self-sabotage by disconnecting completely from your own emotions.', 'Your spiritual journey requires integrating your brilliant mind with the collective heart of humanity. You are a hidden innovator, working quietly to advance the collective consciousness.', 'Do not isolate yourself out of a belief that no one understands you. Embrace your unique brilliance and learn to connect with others emotionally, not just intellectually.'),
('House 12', 'Pisces', 'The subconscious, hidden matters, and spirituality are the absolute core of this placement. You are deeply connected to the collective unconscious and the mystical realms.', 'This is the natural home of Pisces. The boundaries between your conscious mind and the spiritual world are incredibly thin. You require vast amounts of solitude to process the immense energies you absorb.', 'Supreme spiritual intuition, boundless compassion for all living things, the ability to channel profound art or healing, and a natural state of mystical enlightenment.', 'A complete lack of psychological boundaries, getting lost in illusions, addictions, or severe escapism to avoid the harshness of reality, and extreme martyrdom.', 'Your spiritual path is your entire life. You are a natural mystic and healer, but you are highly vulnerable to the dark energies of the world if you do not protect yourself.', 'Establish iron-clad boundaries. You cannot heal the world if you allow yourself to drown in its sorrow. Ground your immense spiritual power in practical reality.');`

	valuesStr := strings.TrimPrefix(rawData, "INSERT INTO houses_data (house_name, zodiac_sign, core_meaning, in_real_life, strengths, challenges, relationships, path_of_growth) VALUES\n")
	valuesStr = strings.TrimSpace(valuesStr)
	valuesStr = strings.TrimSuffix(valuesStr, ";")

	ctx := context.Background()
	conn, err := pgx.Connect(ctx, "postgres://zodiac_user:zodiac_pass@localhost:5432/zodiac_db?sslmode=disable")
	if err != nil {
		log.Fatalf("Unable to connect to database: %v\n", err)
	}
	defer conn.Close(ctx)

	insertQuery := fmt.Sprintf(`
		WITH data(house_name, zodiac_sign, core_meaning, real_life, strengths, challenges, relationships, growth_path) AS (
			VALUES %s
		)
		INSERT INTO placement_interpretations (
			language, factor_type, factor_value_1, factor_value_3, factor_value_2,
			core_meaning, real_life, strengths, challenges, relationships, growth_path
		)
		SELECT 
			'en', 
			'house_in_sign', 
			trim(replace(house_name, 'House', '')), 
			'', 
			zodiac_sign,
			core_meaning, real_life, strengths, challenges, relationships, growth_path
		FROM data
		ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3)
		DO UPDATE SET
			core_meaning = EXCLUDED.core_meaning,
			real_life = EXCLUDED.real_life,
			strengths = EXCLUDED.strengths,
			challenges = EXCLUDED.challenges,
			relationships = EXCLUDED.relationships,
			growth_path = EXCLUDED.growth_path,
			updated_at = CURRENT_TIMESTAMP;
	`, valuesStr)

	tag, err := conn.Exec(ctx, insertQuery)
	if err != nil {
		log.Fatalf("Insert failed: %v", err)
	}

	fmt.Printf("Successfully inserted/updated House 10-12 data! Rows affected: %d\n", tag.RowsAffected())
}
